        if not 2<=W<=w:continue
        r0=ar if meta['top'] else ar-H+1;c0=ac if meta['left'] else ac-W+1
        if not(0<=r0<=h-H and 0<=c0<=w-W):continue
        bycell=[[] for _ in range(area)];all_candidates=[]
        for i,piece in enumerate(pieces):
            pr=min(r for r,c in piece);pc=min(c for r,c in piece)
            ph=max(r for r,c in piece)-pr+1;pw=max(c for r,c in piece)-pc+1
            shape={(r-pr,c-pc):v for (r,c),v in piece.items()}
            offsets=[(pr-r0,pc-c0)] if i==meta['anchor'] else [(r,c) for r in range(H-ph+1) for c in range(W-pw+1)]
            for dr,dc in offsets:
                shifted={(r+dr,c+dc):v for (r,c),v in shape.items()}
                if any(not(0<=r<H and 0<=c<W) or ((r in (0,H-1) or c in (0,W-1)) and v!=base) for (r,c),v in shifted.items()):continue
                entries=[(r*W+c,v) for (r,c),v in shifted.items()];mask=sum(1<<idx for idx,v in entries)
                edges=[]
                for (r,c),v in shifted.items():
                    for rr,cc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                        if 0<=rr<H and 0<=cc<W and (rr,cc) not in shifted:edges.append((rr*W+cc,v))
                can=(i,entries,mask,edges,(r0+dr-pr,c0+dc-pc))
                all_candidates.append(can)
                for idx,v in entries:bycell[idx].append(can)
        board=[-1]*area;owners=[-1]*area;used=set();placement={};full=(1<<area)-1;seen=set()
        def valid(can,mask):
            if can[0] in used or can[2]&mask:return False
            contacts={}
            for j,v in can[3]:
                if owners[j]>=0:contacts.setdefault(owners[j],[]).append((board[j],v))
            return any(all(a==b for a,b in vals) and any(a!=base for a,b in vals)
                       for vals in contacts.values())
