def predict(grid, mode='assembly', *, certificate=None):
    cert=solve(grid) if certificate is None else certificate
    out=deepcopy(cert['output'])
    if mode=='assembly':return out
    if mode not in ('largest_region','raw_largest','smallest_region','first_region','all_regions','largest_color','largest_piece','erase_marker','centered'):raise ValueError('unknown mode')
    if mode=='erase_marker':return [[cert['background'] if v==cert['marker'] else v for v in row] for row in grid]
    if mode=='centered':
        r0,c0,H,W=cert['box'];r1=(len(grid)-H)//2;c1=(len(grid[0])-W)//2
        result=[[cert['background']]*len(grid[0]) for _ in grid]
        for r in range(H):result[r1+r][c1:c1+W]=out[r0+r][c0:c0+W]
        return result
    if mode!='raw_largest':
        cells={(r,c):v for r,row in enumerate(out) for c,v in enumerate(row) if v not in (cert['background'],cert['base'])}
        regions=components(cells,True)
        if not regions:return out
        chosen=[p for p in regions if len(p)==max(map(len,regions))]
        if mode=='smallest_region':chosen=[p for p in regions if len(p)==min(map(len,regions))]
        if mode=='first_region':chosen=regions[:1]
        if mode=='all_regions':chosen=regions
        if mode=='largest_color':
            counts=Counter(v for p in regions for v in p.values());winner=min(counts,key=lambda v:(-counts[v],v))
            chosen=[p for p in regions if next(iter(p.values()))==winner]
        if mode=='largest_piece':
            i=max(range(len(cert['pieces'])),key=lambda i:len(cert['pieces'][i]));dr,dc=cert['offsets'][i]
            chosen=[{(r+dr,c+dc):v for (r,c),v in cert['pieces'][i].items() if v!=cert['base']}]
    else:
        regions=[]
        for i,piece in enumerate(cert['pieces']):
            dr,dc=cert['offsets'][i]
            for p in components({q:v for q,v in piece.items() if v!=cert['base']},True):
                regions.append({(r+dr,c+dc):v for (r,c),v in p.items()})
        chosen=[p for p in regions if len(p)==max(map(len,regions))]
    for p in chosen:
        for r,c in p:out[r][c]=cert['marker']
    return out

