def _pose(grid,pose):
    result=deepcopy(grid)
    if pose>=4:result=[row[::-1] for row in result]
    for _ in range(pose%4):result=[list(row) for row in zip(*result[::-1])]
    return result

def _scene(seed,index,attempt=0):
    rng=random.Random(f'446ef5d2:scene:{seed}:{index}:{attempt}')
    # Cuts go through doubled pixel rows/columns. Continuation across each
    # cut is exact; the solver, not a stored placement, establishes uniqueness.
    if index==9:H=W=18;nr=nc=3;sizeh=sizew=30
    else:
        nr,nc=((2,2),(2,2),(2,3),(3,2),(2,2),(2,3),(2,2),(3,2),(2,3))[index%9]
        H=nr*rng.choice([4,6]);W=nc*rng.choice([4,6])
        sizeh=H+nr*3+2;sizew=W+nc*3+2
    bg,base,marker,p1,p2,p3=rng.sample(range(10),6)
    palette=[base,p1,p2,p3]
    coarse=[[rng.choices(palette,weights=[3,3,2,2])[0] for _ in range((W-2)//2)] for _ in range((H-2)//2)]
    picture=[[base]*W for _ in range(H)]
    for r in range(1,H-1):
        for c in range(1,W-1):picture[r][c]=coarse[(r-1)//2][(c-1)//2]
    # Rectangular fragments plus optional L-shaped amalgamation of adjacent
    # tiles preserve the parent's nonrectangular fragment branch.
    rh=H//nr;cw=W//nc
    fragments=[{(r,c):picture[r][c] for r in range(i*rh,(i+1)*rh) for c in range(j*cw,(j+1)*cw)}
               for i in range(nr) for j in range(nc)]
