def generate(seed=0, sample_index=0, *, difficulty=None, **overrides):
    if type(seed) is not int or not 0<=seed<2**63 or type(sample_index) is not int or sample_index<0:
        raise ValueError('exact nonnegative seed/index required')
    if difficulty not in (None,'easy','medium','hard') or overrides:
        raise ValueError('unsupported generator request')
    stream=int.from_bytes(hashlib.sha256(f'{seed}:{sample_index//10}'.encode()).digest()[:8],'big')%(2**63)
    return deepcopy(bank(stream)[sample_index%10]['input'])

def self_check(grid, *, difficulty=None):
    try:
        solve(grid)
    except (ValueError,TypeError,IndexError) as exc:
        return [{'issue':str(exc)}]
    return []
